import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime.addMonths(int)
 */
public class MutableDateTime_addMonths_TriageGen2Test {











    @Test
    public void testAddMonths_EndOfMonthEdgeCase() {
        // Test adding months where the day of the month might change (e.g., Jan 31 + 1 month -> Feb 28/29)
        // Note: The implementation uses chronology.months().add(), which handles month-end logic.
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1); 
        // Since months == 1 is a special 'do-nothing' case in this specific code snippet,
        // we must use a value != 1 to actually test the chronology logic.

        MutableDateTime dt2 = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt2.addMonths(12); // Using 12 to bypass the (months != 1) check
        assertEquals(2024, dt2.getYear());
        assertEquals(1, dt2.getMonthOfYear());
        assertEquals(31, dt2.getDayOfMonth());

        MutableDateTime dt3 = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt3.addMonths(2); // Jan 31 + 2 months = March 31
        assertEquals(3, dt3.getMonthOfYear());
        assertEquals(31, dt3.getDayOfMonth());
    }
}
